  /**
   * Array of UUIDs, corresponding to the attachments (up to 5) uploaded on the transaction. You can obtain details for each attachment using [Get attachment](/reference/openapi_v2.yml/paths/~1v2~1attachments~1%7Bid%7D/get).
   */
  attachment_ids?: Array<string>;
  /**
   * Object containing URLs to small and medium-sized logos associated with the transaction.
   */
