export type CardDataV1 = {
  /**
   * Event triggering the webhook
   *
   * `created`: the card has been created.
   * `activated`: the card has been activated and can be used.
   * `unlocked`: the card has been unlocked and can be used.
   * `locked`: the card has been locked and cannot be used.
   * `nickname_updated`: the card nickname has been updated.
   * `options_updated`: the card options have been updated.
   * `limits_updated`: the card limits have been updated.
   * `restrictions_updated`: the card restrictions have been updated.
   * `discarded`: the card has been discarded and cannot be used.
   * `expired`: the card has expired and cannot be used.
   *
   */
  event:
    | 'created'
    | 'activated'
    | 'unlocked'
    | 'locked'
    | 'nickname_updated'
    | 'options_updated'
    | 'limits_updated'
    | 'restrictions_updated'
    | 'discarded'
    | 'expired';
  /**
   * Unique card identifier
   */
  id: string;
  /**
   * Display name for the card.
   */
  nickname?: string;
  /**
   * Status of the card.
   * Pending: the card is awaiting PIN to be set or issuing to complete.
   * Live: the card is active and can be used.
   * Paused: the card is paused and cannot be used until un-paused.
   * Stolen: the card has been reported as stolen and cannot be used.
   * Lost: the card has been reported as lost and cannot be used.
   * Pin_blocked: the card has been blocked due to too many wrong PIN attempts. It can still be used for card-not-present transactions.
   * Discarded: the card has been discarded and cannot be used.
   * Expired: the card has expired and cannot be used.
   * Shipped_lost: the card has been lost during shipping and cannot be used.
   * Onhold: the card issuing is on hold due to missing KYC/KYB validation and cannot be used.
   * Order_canceled: the card order has been canceled.
   * Pre_expired: the flash card has reached the end of its validity and cannot be used.
   * Abusive: the card has been reported as abusive and cannot be used.
   */
  status:
    | 'pending'
    | 'live'
    | 'paused'
    | 'stolen'
    | 'lost'
    | 'pin_blocked'
    | 'discarded'
    | 'expired'
    | 'shipped_lost'
    | 'onhold'
    | 'order_canceled'
    | 'pre_expired'
    | 'abusive';
  /**
   * String representing the masked PAN of card.
   */
  masked_pan?: string;
  /**
   * The expiration month. [1-12]
   */
  exp_month?: string;
  /**
   * The expiration year.
   */
  exp_year?: string;
  /**
   * Flag indicating whether the card could withdraw money on an ATM.
   */
  atm_option: boolean;
  /**
   * Flag indicating whether the card could make a payment with NFC mode (contactless).
   */
  nfc_option: boolean;
  /**
   * Flag indicating whether the card could make an online payment.
   */
  online_option: boolean;
  /**
   * Flag indicating whether the card could make a payment outside of France.
   */
  foreign_option: boolean;
  /**
   * Total of withdrawal limit per day. (unit: euro)
   */
  atm_daily_limit?: string;
  /**
   * Flag indicating whether the total amount per day limit should be applied to atm withdrawals
   */
  atm_daily_limit_option: boolean;
  /**
   * Total of ATM limit per month (unit: euro).
   */
  atm_monthly_limit?: string;
  /**
   * Total of payment spend on the current month (unit: euro).
   */
  payment_monthly_limit?: string;
  /**
   * Total of payment limit per day.
   */
  payment_daily_limit?: string;
  /**
   * Flag indicating whether the total amount per day limit should be applied to payments
   */
  payment_daily_limit_option: boolean;
  /**
   * Total of payment limit per transaction.
   */
  payment_transaction_limit?: string;
  /**
   * Flag indicating whether the total amount per transaction limit should be applied to payments
   */
  payment_transaction_limit_option: boolean;
  /**
   * Total amount spent on the card since its creation (unit: euro).
   */
  payment_lifespan_limit?: string;
  active_days: CardActiveDays;
  /**
   * The membership identifier of the card holder.
   */
  holder_id: string;
  /**
   * The id of the bank account to which the card is attached
   */
  bank_account_id: string;
  /**
   * Datetime at which the object was last updated.
   */
  updated_at: string;
  /**
   * Datetime at which the object was created.
   */
  created_at: string;
  /**
   * Type of the card
   */
  card_type: 'debit' | 'prepaid';
  /**
   * Level of the card. A level defines a set of card capabilities and pricing.
   */
  card_level: string;
  category_tags: CardCategories;
  /**
   * Flag indicating whether the card is a renewal card
   */
  renewal: boolean;
  /**
   * Flag indicating whether the card is an upsell child card
   */
  upsell: boolean;
  /**
   * Datetime at which the card will be discarded after being upsold. (upsold_at  + 30 days)
   */
  discarded_at?: string;
};

