export type ExternalTransfersCheckoutData = {
  body?: {
    /**
     * Proof token from a bulk payee verification attempt or skip verification request. Use the token from [bulk verify payee](/api-reference/business-api/payments-transfers/sepa-transfers/verify-payee/bulk-verify-payee#tag/Bulk-Verify-SEPA-Payee/operation/bulkVerifyPayee) or [skip verify payee](/api-reference/business-api/payments-transfers/sepa-transfers/verify-payee/skip-verify-payee#tag/Skip-Verify-SEPA-Payee/operation/skipVerifyPayee) to opt-out from the verification.
     */
    vop_proof_token: string;
    /**
     * IBAN of account to debit.
     */
    debit_iban: string;
    external_transfers: Array<{
      /**
       * IBAN of account to credit.
       */
      credit_iban: string;
      /**
       * The name of the credit account.
       */
      credit_account_name: string;
      /**
       * Can be either the currency of the `debit_iban` or the currency of the creditor. Allowed values is only `EUR` at the moment.
       */
      credit_account_currency: string;
      /**
       * Transfer reference that can be used to enter transfer details to further describe the transfer. Maximum `reference` length is `140` characters.
       */
      reference: string;
      note?: string;
      /**
       * Allowed values is only `EUR` at the moment.
       */
      currency: string;
      /**
       * The transfers will be executed on the `scheduled_date` (YYYY-MM-DD) at midnight (GMT).
       */
      scheduled_date?: string;
      /**
       * Corresponds to the amount of the transaction in the `currency` of the bank account. Amounts must be https://www.w3.org/TR/payment-request/#dfn-valid-decimal-monetary-value.
       */
      amount: string;
      /**
       * This is a unique string (we advise to use a `uuid`) that identifies a transfer. This is used by Qonto to prevent "double spending" by accidentaly replaying the same API call.
       *
       * The `idempotency_key` must be the same for all the call sequence used during the SCA flow :
       *
       * - For each transfer, the `idempotency_key` is first set on the initial call, which will trigger the SCA flow.
       * - The **same** `idempotency_key` **must** be used on the final call that includes the SCA token.
       *
       * This is so because the two calls are actually related to the **same transfer**.
       */
      idempotency_key?: string;
      /**
       * You can link up to 5 attachments per transfer by passing the `attachment_ids` parameter. You can upload your attachments using our [POST /v2/attachments](/api-reference/business-api/endpoints/attachments/upload-an-attachment) endpoint.
       * <br>**Note: For SEPA transfers above 30,000 EUR at least one attachment is required**
       *
       */
      attachment_ids?: Array<string>;
    }>;
  };
  headers?: {
    /**
     * Required only for Sandbox API requests; to get one, please sign up to the [Developer Portal](https://developers.qonto.com/).
     */
    'X-Qonto-Staging-Token'?: string;
  };
  path?: never;
  query?: never;
  url: '/v2/external_transfers/checkout';
};

